n    --exv-bronce: var(--gp-ambar);\n    --exv-bronce-oscuro: var(--gp-azul-texto);\n    --exv-bronce-tinte: var(--gp-azul-suave);\n    --exv-sobre-acento: var(--gp-sobre-acento);\n    --exv-verde: var(--gp-verde-texto);\n    --exv-verde-tinte: var(--gp-verde-suave);\n    --exv-linea: var(--gp-linea-fuerte);\n    --exv-linea-suave: var(--gp-linea);\n    --exv-alerta: var(--gp-coral);\n    --exv-alerta-tinte: var(--gp-coral-suave);\n    --exv-a12: var(--gp-azul-texto);\n    --exv-a12-tinte: var(--gp-azul-suave);\n    --exv-radio: var(--gp-radio);\n    color: var(--exv-tinta);\n}\n\n.exv-contenido { max-width: 96rem; margin: 0 auto; }\n\n.exv-solo-impresion { display: none; }\n\n/* Encabezado */\n.exv-titulo {\n    display: flex;\n    align-items: center;\n    gap: 1rem;\n    flex-wrap: wrap;\n    margin-bottom: 1.25rem;\n}\n.exv-titulo-texto { flex: 1; min-width: 240px; }\n.exv-titulo-texto h2 { font-size: 1.5rem; line-height: 1.2; font-weight: 800; margin: .2rem 0 0; color: var(--exv-tinta); }\n.exv-eyebrow { font-size: .72rem; letter-spacing: .12em; text-transform: uppercase; color: var(--exv-bronce-oscuro); }\n.exv-titulo-acciones { display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; }\n.exv-titulo-acciones select {\n    font-size: .85rem;\n    padding: .5rem .6rem;\n    border: 1px solid var(--exv-linea);\n    border-radius: var(--exv-radio);\n    background: var(--exv-control);\n    color: var(--exv-tinta);\n    max-width: 100%;\n}\n\n/* Botones */\n.exv-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: .4rem;\n    font-size: .82rem;\n    font-weight: 600;\n    border: 1px solid var(--exv-linea);\n    background: var(--exv-control);\n    color: var(--exv-tinta-suave);\n    padding: .5rem .85rem;\n    border-radius: var(--exv-radio);\n    cursor: pointer;\n    transition: border-color .12s, color .12s, background .12s;\n}\n.exv-btn:hover:not(:disabled) { border-color: var(--exv-bronce); color: var(--exv-bronce-oscuro); }\n.exv-btn:disabled { opacity: .55; cursor: not-allowed; }\n.exv-btn-primario { background: var(--exv-bronce); border-color: var(--exv-bronce); color: var(--exv-sobre-acento); }\n.exv-btn-primario:hover:not(:disabled) { background: #F5B62E; border-color: #F5B62E; color: var(--exv-sobre-acento); }\n.exv-btn-peligro:hover:not(:disabled) { border-color: var(--exv-alerta); color: var(--exv-alerta); }\n\n/* Distribución */\n.exv-shell {\n    display: grid;\n    grid-template-columns: 330px minmax(0, 1fr);\n    gap: 1.5rem;\n    align-items: start;\n}\n.exv-shell.plegada { grid-template-columns: minmax(0, 1fr); }\n.exv-tablero { min-width: 0; }\n\n/* Configuración inicial: se confirma una vez, antes de poder chequear */\n.exv-confirmar {\n    padding: 1.25rem 1.4rem;\n    background: var(--exv-tarjeta);\n    border: 1px solid var(--exv-linea);\n    border-top: 3px solid var(--exv-bronce);\n    border-radius: var(--exv-radio);\n}\n.exv-confirmar h3 { margin: 0 0 .5rem; font-size: 1.05rem; font-weight: 700; color: var(--exv-tinta); }\n.exv-confirmar p { margin: 0 0 1rem; font-size: .88rem; line-height: 1.5; color: var(--exv-tinta-suave); }\n.exv-confirmar-pie {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n    gap: .75rem;\n    padding-top: .9rem;\n    font-size: .88rem;\n    font-weight: 600;\n    border-top: 1px solid var(--exv-linea-suave);\n}\n\n/* Configuración plegada: se ve de un vistazo sin ocupar la pantalla */\n.exv-config-resumen {\n    display: flex;\n    flex-wrap: wrap;\n    gap: .35rem 1.25rem;\n    padding: .55rem .9rem;\n    margin-bottom: 1rem;\n    font-size: .8rem;\n    color: var(--exv-tinta-suave);\n    background: var(--exv-tarjeta);\n    border: 1px solid var(--exv-linea-suave);\n    border-radius: var(--exv-radio);\n}\n.exv-config-resumen b { margin-right: .25rem; font-weight: 700; color: var(--exv-tinta); }\n\n/* Panel de configuración */\n.exv-config {\n    position: sticky;\n    top: 1rem;\n    max-height: calc(100dvh - 2rem);\n    overflow-y: auto;\n    background: var(--exv-tarjeta);\n    border: 1px solid var(--exv-linea);\n    border-radius: var(--exv-radio);\n}\n.exv-config-head {\n    position: sticky;\n    top: 0;\n    z-index: 2;\n    display: flex;\n    justify-content: space-between;\n    align-items: baseline;\n    padding: .85rem 1.1rem;\n    background: var(--exv-tarjeta);\n    border-bottom: 1px solid var(--exv-linea-suave);\n}\n.exv-config-head h2 { font-size: .82rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; margin: 0; color: var(--exv-tinta); }\n.exv-config-head span { font-size: .75rem; color: var(--exv-tinta-tenue); }\n.exv-config fieldset { border: 0; margin: 0; padding: 1rem 1.1rem; border-bottom: 1px solid var(--exv-linea-suave); min-width: 0; }\n.exv-config fieldset:last-of-type { border-bottom: 0; }\n.exv-config legend {\n    display: block;\n    float: left;\n    width: 100%;\n    padding: 0;\n    margin-bottom: .6rem;\n    font-size: .7rem;\n    font-weight: 700;\n    letter-spacing: .1em;\n    text-transform: uppercase;\n    color: var(--exv-bronce-oscuro);\n}\n.exv-config legend small { font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--exv-tinta-tenue); }\n.exv-config legend + * { clear: both; }\n.exv-tipos { background: var(--exv-bronce-tinte); }\n.exv-tipo-grupo { margin-bottom: .5rem; }\n.exv-tipo-grupo:last-child { margin-bottom: 0; }\n.exv-tipo-titulo {\n    margin: .5rem 0 .2rem;\n    padding-top: .4rem;\n    border-top: 1px solid var(--exv-linea);\n    font-size: .68rem;\n    font-weight: 700;\n    letter-spacing: .06em;\n    text-transform: uppercase;\n    color: var(--exv-bronce-oscuro);\n}\n.exv-tipo-grupo:first-of-type .exv-tipo-titulo { margin-top: 0; padding-top: 0; border-top: 0; }\n\n.exv-opt {\n    display: flex;\n    align-items: flex-start;\n    gap: .6rem;\n    padding: .32rem 0;\n    font-size: .88rem;\n    line-height: 1.35;\n    font-weight: 400;\n    color: var(--exv-tinta-suave);\n    cursor: pointer;\n    user-select: none;\n}\n.exv-opt:hover { color: var(--exv-tinta); }\n.exv-opt input { flex-shrink: 0; width: 15px; height: 15px; margin: .12rem 0 0; accent-color: var(--gp-azul); cursor: pointer; }\n.exv-opt input:disabled { cursor: not-allowed; }\n.exv-opt-sub { display: block; font-size: .74rem; color: var(--exv-tinta-tenue); }\n\n.exv-seg { display: flex; gap: .4rem; clear: both; }\n.exv-seg label {\n    position: relative;\n    flex: 1;\n    padding: .5rem .3rem;\n    text-align: center;\n    font-size: .95rem;\n    font-weight: 600;\n    color: var(--exv-tinta-suave);\n    border: 1px solid var(--exv-linea);\n    border-radius: var(--exv-radio);\n    cursor: pointer;\n    transition: border-color .12s;\n}\n.exv-seg label:hover { border-color: var(--exv-bronce); }\n.exv-seg label.activa { background: var(--exv-bronce); border-color: var(--exv-bronce); color: var(--exv-sobre-acento); }\n.exv-seg label:focus-within { outline: 2px solid var(--exv-a12); outline-offset: 1px; }\n.exv-seg input { position: absolute; opacity: 0; pointer-events: none; }\n.exv-seg-tag { display: block; margin-top: .1rem; font-size: .62rem; font-weight: 400; opacity: .8; }\n\n/* Barra de avance */\n.exv-barra {\n    display: flex;\n    align-items: center;\n    gap: 1.1rem;\n    flex-wrap: wrap;\n    padding: .9rem 1.15rem;\n    margin-bottom: 1.1rem;\n    background: var(--exv-tarjeta);\n    border: 1px solid var(--exv-linea);\n    border-radius: var(--exv-radio);\n}\n.exv-medidor { flex: 1; min-width: 180px; }\n.exv-medidor-top { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: .4rem; }\n.exv-medidor-top b { font-size: 1.05rem; font-weight: 700; }\n.exv-medidor-top b span { color: var(--exv-bronce); font-variant-numeric: tabular-nums; }\n.exv-medidor-top em { font-style: normal; font-size: .78rem; color: var(--exv-tinta-tenue); font-variant-numeric: tabular-nums; }\n.exv-pista { height: 7px; background: var(--exv-linea-suave); border-radius: 99px; overflow: hidden; }\n.exv-relleno { height: 100%; background: var(--gp-verde); transition: width .35s cubic-bezier(.4, 0, .2, 1); }\n.exv-relleno.completo { background: var(--gp-verde-texto); }\n.exv-barra-acciones { display: flex; gap: .5rem; flex-wrap: wrap; align-items: center; }\n.exv-radicar-pista { font-size: .8rem; font-weight: 600; color: var(--exv-alerta); }\n\n/* Notas y avisos */\n.exv-nota, .exv-aviso {\n    padding: .6rem .9rem;\n    margin-bottom: 1rem;\n    font-size: .84rem;\n    line-height: 1.45;\n    border-radius: var(--exv-radio);\n}\n.exv-nota { background: var(--exv-a12-tinte); border-left: 3px solid var(--exv-a12); color: var(--exv-tinta); }\n.exv-nota small { display: block; margin-top: .25rem; font-size: .78rem; }\n.exv-aviso { background: var(--exv-alerta-tinte); border: 1px solid rgba(255, 122, 92, .4); border-left: 3px solid var(--exv-alerta); color: var(--exv-tinta); }\n\n/* Secciones */\n.exv-seccion { margin-bottom: 1.5rem; }\n.exv-seccion-head {\n    display: flex;\n    align-items: baseline;\n    gap: .75rem;\n    margin-bottom: .6rem;\n    padding-bottom: .4rem;\n    border-bottom: 2px solid var(--exv-tinta);\n}\n.exv-num { flex-shrink: 0; padding: .12rem .5rem; font-size: .78rem; font-weight: 600; color: var(--exv-sobre-acento); background: var(--exv-bronce); border-radius: 2px; }\n.exv-seccion-head h3 { flex: 1; margin: 0; font-size: 1.06rem; font-weight: 700; color: var(--exv-tinta); }\n.exv-cita { font-size: .74rem; text-align: right; color: var(--exv-tinta-tenue); }\n.exv-subhead {\n    margin: .9rem 0 .35rem;\n    padding-left: .1rem;\n    font-size: .8rem;\n    font-weight: 600;\n    letter-spacing: .04em;\n    text-transform: uppercase;\n    color: var(--exv-bronce-oscuro);\n}\n.exv-subhead-sector { margin-top: 1rem; padding-bottom: .15rem; font-size: .9rem; color: var(--exv-tinta); border-bottom: 2px solid var(--exv-bronce); }\n\n/* Requisito */\n.exv-item {\n    padding: .7rem .9rem;\n    margin-bottom: .4rem;\n    background: var(--exv-tarjeta);\n    border: 1px solid var(--exv-linea-suave);\n    border-radius: var(--exv-radio);\n    transition: border-color .12s, background .12s;\n}\n.exv-item:hover { border-color: var(--exv-linea); }\n.exv-item.cumplido { background: var(--exv-verde-tinte); border-color: rgba(62, 171, 43, .4); }\n.exv-item-principal { display: flex; gap: .8rem; align-items: flex-start; margin: 0; font-weight: 400; cursor: pointer; }\n.exv-item-principal input { flex-shrink: 0; width: 17px; height: 17px; margin: .15rem 0 0; accent-color: var(--gp-verde); cursor: pointer; }\n.exv-item-principal input:disabled { cursor: not-allowed; }\n.exv-item-cuerpo { flex: 1; min-width: 0; }\n.exv-item-tags { display: flex; gap: .35rem; align-items: center; flex-wrap: wrap; margin-bottom: .25rem; }\n.exv-codigo { padding: .08rem .4rem; font-size: .7rem; font-weight: 500; color: var(--exv-bronce-oscuro); background: var(--exv-bronce-tinte); border-radius: 2px; }\n.exv-fuente { padding: .06rem .35rem; font-size: .64rem; font-weight: 600; border-radius: 2px; }\n.exv-fuente-a12 { color: var(--exv-a12); background: var(--exv-a12-tinte); }\n.exv-fuente-ot { color: var(--exv-tinta-suave); background: var(--gp-superficie-3); }\n.exv-item-texto { font-size: .93rem; line-height: 1.42; color: var(--exv-tinta); }\n.exv-item.cumplido .exv-item-texto { color: var(--exv-tinta-suave); }\n.exv-item-nota { display: block; margin-top: .25rem; font-size: .78rem; font-style: italic; color: var(--exv-tinta-tenue); }\n.exv-item-meta { margin: .35rem 0 0 calc(17px + .8rem); font-size: .76rem; color: var(--exv-verde); }\n.exv-item-acciones { display: flex; flex-wrap: wrap; gap: .35rem; margin: .45rem 0 0 calc(17px + .8rem); }\n.exv-item.no-cuenta { opacity: .72; }\n.exv-estado { padding: .06rem .4rem; font-size: .66rem; font-weight: 600; color: var(--exv-tinta-suave); background: var(--gp-superficie-3); border-radius: 2px; }\n.exv-estado-no_aplica_pendiente, .ex